contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint withdrawValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        c.sendMoney(address(this), amount); if (__ESBMC_reverted()) return;

        uint countAfterDeposit = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool revertedWithdraw;
        c.withdraw(withdrawValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedWithdraw = true;
        } else {
            revertedWithdraw = false;
        }

        uint countAfterWithdraw = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool revertedWithdrawAll;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedWithdrawAll = true;
        } else {
            revertedWithdrawAll = false;
        }

        uint countAfterWithdrawAll = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            countAfterDeposit == countBefore &&
            countAfterWithdraw == countBefore &&
            countAfterWithdrawAll == countBefore
        );
    }

    receive() external payable {}
}

